            for i, cand in enumerate(unassigned):
                dem = demands.get(cand, 0)
                if load + dem > capacity:
                    continue
                delta = dist(last, cand) + dist(cand, depot) - dist(last, depot)
                if best_delta is None or delta < best_delta or (delta == best_delta and cand < unassigned[best_i]):
                    best_delta = delta
                    best_i = i
            if best_i == -1:
                break
            cand = unassigned.pop(best_i)
            route.append(cand)
            load += demands.get(cand, 0)

        routes.append(route)

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    if missing:
        routes = [r for r in routes if r]
        for c in missing:
            best_r = -1
            best_pos = -1
            best_delta = None
            dem = demands.get(c, 0)
            for ri, r in enumerate(routes):
                if route_load(r) + dem > capacity:
                    continue
                for pos in range(len(r) + 1):
                    prev = depot if pos == 0 else r[pos - 1]
                    nxt = depot if pos == len(r) else r[pos]
                    delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    if best_delta is None or delta < best_delta or (delta == best_delta and (ri < best_r or (ri == best_r and pos < best_pos))):
                        best_delta = delta
                        best_r = ri
                        best_pos = pos
            if best_r == -1:
                routes.append([c])
            else:
                routes[best_r].insert(best_pos, c)

    routes = [r for r in routes if r]

    cleaned = []
    seen = {}
    for r in routes:
        nr = []
        for c in r:
            if seen.get(c, 0) == 0:
                nr.append(c)
                seen[c] = 1
        if nr:
            cleaned.append(nr)
    routes = cleaned

    for c in customers:
        if seen.get(c, 0) == 0:
            routes.append([c])

    return routes
